-- Generic introductory revision codes are examples, not institutional unit allocations.
insert into public.ace_quizzes(title,course_code,description) select 'Microeconomics · Applied Markets','ECO 101','Real-world supply, demand, elasticity and opportunity cost calculations.' where not exists(select 1 from public.ace_quizzes where title='Microeconomics · Applied Markets');
with target as (select id from public.ace_quizzes where title='Microeconomics · Applied Markets' limit 1) insert into public.ace_questions(quiz_id,prompt,options,correct_index,explanation,sort_order) select target.id,x.prompt,x.options::jsonb,x.correct_index,x.explanation,x.sort_order from target cross join (values ('A student spends KSh 500 on a concert ticket instead of buying a textbook. In economic terms the main opportunity cost is:','["The value of the next best alternative forgone","Only the money printed on the ticket","Every possible alternative added together","The seller''s profit"]',0,'Opportunity cost is the value of the next best alternative that is given up.',1),('When demand increases but short-run supply remains unchanged, competitive equilibrium price generally:','["Rises","Falls to zero","Must stay unchanged","Becomes a legally fixed price"]',0,'A rightward demand shift normally raises equilibrium price and quantity along an unchanged upward-sloping supply curve.',2),('The price of a good rises from KSh 100 to KSh 110 while quantity demanded falls from 100 to 80. Over this interval demand is:','["Sensitive to price changes","Perfectly inelastic","Independent of price by definition","Necessarily upward sloping"]',0,'Quantity changes materially when price rises; interpreting elasticity precisely would require a chosen calculation method.',3),('A binding minimum price set above equilibrium commonly results in:','["Excess supply","Excess demand","An automatic fall in production costs","No incentive effects"]',0,'A price floor above equilibrium tends to cause quantity supplied to exceed quantity demanded.',4),('A business can produce either 10 chairs or 20 tables with the same resources. The opportunity cost of one chair is:','["Two tables","Half a table","Ten tables","Twenty chairs"]',0,'Giving up 20 tables for 10 chairs implies two tables forgone per chair.',5)) as x(prompt,options,correct_index,explanation,sort_order) on conflict(quiz_id,sort_order) do nothing;
insert into public.ace_quizzes(title,course_code,description) select 'Financial Accounting · Transaction Practice','ACC 101','Applied debit-credit, accounting equations and interpretation of simple records.' where not exists(select 1 from public.ace_quizzes where title='Financial Accounting · Transaction Practice');
with target as (select id from public.ace_quizzes where title='Financial Accounting · Transaction Practice' limit 1) insert into public.ace_questions(quiz_id,prompt,options,correct_index,explanation,sort_order) select target.id,x.prompt,x.options::jsonb,x.correct_index,x.explanation,x.sort_order from target cross join (values ('A business receives KSh 15,000 cash from its owner as capital. Which accounts increase?','["Cash and owner equity","Revenue and accounts payable","Rent and depreciation","Loan expense and inventory"]',0,'The owner contributes cash, increasing assets and equity.',1),('A company pays KSh 4,000 cash to settle an existing supplier balance. What happens?','["Cash and liabilities both decrease","Cash and revenue both increase","Assets and equity both increase","Expenses and capital both increase"]',0,'Payment reduces cash assets and the supplier liability by the same amount.',2),('Services are provided on credit for KSh 8,000. The usual entry increases:','["Accounts receivable and service revenue","Cash and accounts payable","Inventory and a loan","Land and depreciation"]',0,'On credit, income is earned and a receivable arises before cash is collected.',3),('A business bought equipment for KSh 30,000 cash. Ignoring transaction charges, total assets immediately:','["Remain unchanged","Increase by KSh 30,000","Decrease by KSh 30,000","Increase by KSh 60,000"]',0,'One asset (cash) decreases as another asset (equipment) increases.',4),('At year-end, earned wages of KSh 6,000 remain unpaid. The accrual generally records:','["Wages expense and wages payable","Cash and capital","Prepaid rent and sales revenue","Unearned income and land"]',0,'An accrued expense records the cost incurred and a liability before cash payment.',5)) as x(prompt,options,correct_index,explanation,sort_order) on conflict(quiz_id,sort_order) do nothing;
